using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

internal static class HudExportHotbarVerification {
 static readonly byte[] Mask={0x25,0xa8,0x7e,0x91};
 static byte[] Crypt(byte[] bytes){return bytes.Select((b,n)=>(byte)(b^Mask[n%4])).ToArray();}
 internal static byte[] Encode(string text,bool nul=true){var payload=Encoding.UTF8.GetBytes(text+(nul?"\0":""));return Encoding.ASCII.GetBytes(Convert.ToBase64String(Crypt(BitConverter.GetBytes(payload.Length).Concat(payload).ToArray())));}
 static string Decode(byte[] bytes){var clear=Crypt(Convert.FromBase64String(Encoding.UTF8.GetString(bytes).TrimStart('\ufeff')));return Encoding.UTF8.GetString(clear,4,clear.Length-4).TrimEnd('\0');}
 static void Check(bool value,string text){if(!value)throw new Exception(text);}
 internal static string Fixture(){return "{\r\n\"Name\":\"Mi HUD · ñ\",\"Group\":3,\"Edit\":{"+string.Join(",",NativeHudFile.Tags.Select((tag,n)=>"\""+tag+"\":{\"Hide\":"+(n==1?"true":"false")+",\"Extra\":{\"Hide\":false},\"Size\":0.9300001,\"Tag\":\""+tag+"\"}"))+",\"Chat\":{\"Tag\":\"Chat\",\"Hide\":false,\"HO\":77.25},\"Minimap\":{\"Hide\":true}}}";}
 static void Rejected(byte[] bytes){bool rejected=false;try{HudExportHotbar.Build(bytes);}catch(InvalidDataException){rejected=true;}Check(rejected,"Unsupported or ambiguous HUD export must be rejected");}
 static void HideExpected(Dictionary<string,object> edit){foreach(string tag in NativeHudFile.Tags){object row;if(edit.TryGetValue(tag,out row))((Dictionary<string,object>)row)["Hide"]=true;else edit.Add(tag,new Dictionary<string,object>{{"Tag",tag},{"Hide",true}});}}
 static void VerifySparse(){var json=NativeHudFile.Json();for(int mask=0;mask<8;mask++){
  var source=json.Deserialize<Dictionary<string,object>>(Fixture());var edit=(Dictionary<string,object>)source["Edit"];for(int n=0;n<3;n++)if((mask&(1<<n))==0)edit.Remove(NativeHudFile.Tags[n]);
  byte[] bytes=Encode(json.Serialize(source)),before=(byte[])bytes.Clone();var result=HudExportHotbar.Build(bytes);var actual=json.Deserialize<Dictionary<string,object>>(Decode(result));var expected=json.Deserialize<Dictionary<string,object>>(Decode(bytes));HideExpected((Dictionary<string,object>)expected["Edit"]);
  Check(NativeHudFile.Canonical(actual)==NativeHudFile.Canonical(expected)&&bytes.SequenceEqual(before),"Every sparse subset preserves existing layout and source bytes; only bar visibility overrides added");
  var output=(Dictionary<string,object>)actual["Edit"];for(int n=0;n<3;n++)if((mask&(1<<n))==0){var added=(Dictionary<string,object>)output[NativeHudFile.Tags[n]];Check(added.Count==2&&(bool)added["Hide"]&&Convert.ToString(added["Tag"])==NativeHudFile.Tags[n],"Missing bars get Tag/Hide only, never guessed coordinates, scale or anchors");}
  Check(HudExportHotbar.Build(result).SequenceEqual(result),"Sparse copy is idempotent; no repeated rows or changes");
 }
 var alias=json.Deserialize<Dictionary<string,object>>(Fixture());var rows=(Dictionary<string,object>)alias["Edit"];rows["Alias"]=rows["QuickSlotSkill1"];rows.Remove("QuickSlotSkill1");Rejected(Encode(json.Serialize(alias)));
 }
 internal static void Run(string root){VerifySparse();string folder=Path.Combine(root,"hud-export-cases");Directory.CreateDirectory(folder);string text=Fixture();byte[] original=Encode(text),prepared=HudExportHotbar.Build(original);string expected=text.Replace("\"Hide\":false,\"Extra\"","\"Hide\":true,\"Extra\"");Check(Decode(prepared)==expected,"Only the exact skill-bar Hide tokens change; all other JSON text, floats, name and unrelated visibility remain intact");Check(HudExportHotbar.Build(prepared).SequenceEqual(prepared),"Prepared payload is idempotent");Check(Decode(HudExportHotbar.Build(Encode(text,false)))==expected,"Exports without NUL also preserve payload convention");var bom=new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes("\r\n"+Encoding.ASCII.GetString(original)+"\r\n")).ToArray();Check(Decode(HudExportHotbar.Build(bom))==expected,"UTF8 BOM and Base64 line breaks are accepted");
  bool emptyRejected=false;try{HudExportHotbar.Build(Encode("{\"Name\":\"Empty\",\"Group\":3,\"Edit\":{}}"));}catch(InvalidDataException ex){emptyRejected=ex.Message==HudExportHotbar.EmptyPreset;}Check(emptyRejected,"A structurally valid empty export must receive its specific save/export instruction");
  Rejected(Encoding.UTF8.GetBytes("not an export"));Rejected(Encode("{\"Edit\":{}}"));Rejected(Encode(text.Replace("\"Group\":3","\"Group\":3,\"Group\":4")));Rejected(Encode(text.Replace("\"Group\":3","\"Group\":3,\"Gr\\u006fup\":4")));Rejected(Encode(text.Replace("\"Hide\":false,\"Extra\"","\"Hide\":false,\"Hide\":true,\"Extra\"")));Rejected(Encode(text.Replace("\"Hide\":false,\"Extra\"","\"Hide\":0,\"Extra\"")));Rejected(Encode(text.Replace("\"Tag\":\"QuickSlotSkill1\"","\"Tag\":\"Chat\"")));Rejected(Encode(text+" trailing"));Rejected(new byte[1024*1024+1]);var bad=Crypt(Convert.FromBase64String(Encoding.ASCII.GetString(original)));bad[0]++;Rejected(Encoding.ASCII.GetBytes(Convert.ToBase64String(Crypt(bad))));
  string source=Path.Combine(folder,"Mi HUD ñ.dat");File.WriteAllBytes(source,original);string unrelated=Path.Combine(folder,"DeviceSetting_V2.dat");File.WriteAllBytes(unrelated,new byte[]{1,2,3});var result=HudExportHotbar.Create(source);Check(Path.GetFileName(result.File)=="Helper_HiddenHotbar(Mi HUD ñ).dat"&&File.ReadAllBytes(result.File).SequenceEqual(prepared)&&File.ReadAllBytes(source).SequenceEqual(original),"Create a named import copy beside the selected export while retaining every original byte");Check(File.ReadAllBytes(unrelated).SequenceEqual(new byte[]{1,2,3}),"Creating an export copy never touches the game's DeviceSetting");var again=HudExportHotbar.Create(source);Check(again.Reused&&again.File==result.File,"Identical existing copy is reused without rewriting");File.WriteAllText(result.File,"keep existing file");var collision=HudExportHotbar.Create(source);Check(collision.File!=result.File&&File.ReadAllText(result.File)=="keep existing file"&&File.ReadAllBytes(source).SequenceEqual(original),"Name collisions create a numbered copy without overwriting either existing file");bool blocked=false;try{HudExportHotbar.Create(unrelated);}catch(InvalidDataException){blocked=true;}Check(blocked,"DeviceSetting is not an exported HUD and cannot be selected");
  var options=new SkillSlotsOptions{PreparedHudFile=collision.File,HideNativeHotbar=true};var json=NativeHudFile.Json();var stored=SkillSlotsOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{skillSlots=options})));Check(stored.PreparedHudFile==collision.File,"The prepared-copy path survives restart");
  string real=Path.Combine(root,"hud-export-fixture.dat");bool realChecked=File.Exists(real);if(realChecked){byte[] before=File.ReadAllBytes(real);var output=HudExportHotbar.Build(before);var a=json.Deserialize<Dictionary<string,object>>(Decode(before));var b=json.Deserialize<Dictionary<string,object>>(Decode(output));var edit=(Dictionary<string,object>)a["Edit"];HideExpected(edit);Check(NativeHudFile.Canonical(a)==NativeHudFile.Canonical(b)&&File.ReadAllBytes(real).SequenceEqual(before),"Real standalone export preserves existing layout and adds only missing bar visibility, never its source");}
  File.WriteAllText(Path.Combine(root,"hud-export-test.txt"),"PASS: standalone HUD copy; three bar visibility overrides, all8 sparse subsets and no guessed geometry; retained names/coordinates/formatting and original bytes; NUL/BOM/whitespace; duplicate/escaped duplicate/type/tag/length/size rejection; named non-overwriting copy, collision and reuse; native settings untouched; saved prepared path; read-only real export checked: "+realChecked+". No game import, input or live settings changes.");
 }
}
